<?php

namespace App\Http\Controllers;

use App\Models\Todo;
use Illuminate\Http\Request;

class TodoController extends Controller
{
    // Tampilkan semua todo
    public function index()
    {
        $todos = Todo::orderByDesc('created_at')->get();
        return view('todos.index', compact('todos'));
    }

    // Form tambah todo
    public function create()
    {
        return view('todos.create');
    }

    // Simpan todo baru
    public function store(Request $request)
    {
        $request->validate(['title' => 'required|max:255']);
        Todo::create($request->only('title'));
        return redirect()->route('todos.index')
                         ->with('success', 'Todo berhasil ditambahkan');
    }

    // Form edit
    public function edit(Todo $todo)
    {
        return view('todos.edit', compact('todo'));
    }

    // Update todo
    public function update(Request $request, Todo $todo)
    {
        $request->validate(['title' => 'required|max:255']);
        $todo->update($request->only('title'));
        return redirect()->route('todos.index')
                         ->with('success', 'Todo berhasil diubah');
    }

    // Hapus todo
    public function destroy(Todo $todo)
    {
        $todo->delete();
        return redirect()->route('todos.index')
                         ->with('success', 'Todo dihapus');
    }

    // Toggle status selesai
    public function toggle(Todo $todo)
    {
        $todo->completed = ! $todo->completed;
        $todo->save();
        return back();
    }
}
```

